 655|// (keeps the llama<->ggml-cuda link at the existing backend boundary) and runs it on sc_dev. Returns false
*656|// for non-DiffusionGemma / no sc_dev / non-CUDA(/ROCm/MUSA) builds so the caller falls back to the host path.
*657|typedef bool (*dg_cuda_sample_fn)(struct ggml_tensor *, const float *, int *, float *, int *, int, float);
 658|
*659|bool llama_diffusion_device_sample(const struct llama_model * model, const float * u, int * argmax,
 660|                                   float * entropy, int * sampled, int n_tokens, float inv_temp) {
 661|    const auto * dm = dynamic_cast<const llama_model_diffusion_gemma *>(model);
 662|    if (!dm || dm->sc_dev == nullptr || !u || !argmax || !entropy || !sampled || n_tokens <= 0) {
...
 664|    }
*665|    // The ggml-cuda backend registers under a build-specific name (CUDA / ROCm / MUSA) but exports the same
 666|    // diffusion-sample proc address from a single source, so probe all three to reach the device sampler on
*667|    // HIP and MUSA builds too.
*668|    ggml_backend_reg_t reg = ggml_backend_reg_by_name("CUDA");
*669|    if (!reg) { reg = ggml_backend_reg_by_name("ROCm"); }
*670|    if (!reg) { reg = ggml_backend_reg_by_name("MUSA"); }
 671|    if (!reg) {
 672|        return false;
 673|    }
*674|    static dg_cuda_sample_fn fn =
*675|        (dg_cuda_sample_fn) ggml_backend_reg_get_proc_address(reg, "ggml_backend_cuda_diffusion_sample");
 676|    if (!fn) {
 677|        return false;
 678|    }

