// Archive the live omp session using the omp-archive plugin's own core (run outside the omp
// process, same code path as /archive), including the standalone HTML viewer export.
import { buildSessionArchive } from "/tmp/omp-archive-main/extensions/archive-core.ts";

const stem = "2026-10-16T02-45-18-910Z_01a14299-81be-72f5-b71b-2c1d03aa0db9";
const sessionFile = `/home/asdf/.omp/agent/sessions/-Downloads/${stem}.jsonl`;

const omitted: string[] = [];
let viewerHtmlPath: string | undefined;
try {
	const { exportFromFile } = await import("@oh-my-pi/pi-coding-agent/export/html");
	viewerHtmlPath = await exportFromFile(sessionFile, { outputPath: `/tmp/archive-run/viewer-${stem}.html` });
} catch (err) {
	omitted.push(`viewer.html: ${err instanceof Error ? err.message : String(err)}`);
}

const { zip, manifest } = await buildSessionArchive({
	sessionFile,
	sessionId: "01a14299-81be-72f5-b71b-2c1d03aa0db9",
	cwd: "/home/asdf/Downloads",
	title: "Adapt llama.cpp PR #24423 (DiffusionGemma) for the SYCL backend",
	includeArtifacts: true,
	...(viewerHtmlPath ? { viewerHtmlPath } : {}),
	omitted,
});

const out = `/home/asdf/Downloads/sycl-work/omp-archive-${stem}.zip`;
await Bun.write(out, new Uint8Array(zip));
console.log(JSON.stringify({
	out,
	files: manifest.totals.files,
	bytes: manifest.totals.bytes,
	mainEntries: manifest.main.entries,
	subagents: manifest.subagents.map(s => `${s.key}:${s.entries}`),
	completedJobs: manifest.jobs.completed,
	omitted: manifest.omitted,
}, null, 2));

